from fastapi import FastAPI, File, Form, UploadFile
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.post("/test")
async def test_endpoint(form_data: str = Form(...), file_data: bytes = File(...)):
    return {"form_data": form_data, "file_data": file_data}

client = TestClient(app)

def test_form_then_file():
    # This should work
    response = client.post(
        "/test",
        data={"form_data": "hello"},
        files={"file_data": b"world"}
    )
    print(f"Status: {response.status_code}")
    print(f"Body: {response.json()}")
    assert response.status_code == 200

def test_file_then_form():
    # This should also work
    @app.post("/test2")
    async def test_endpoint2(file_data: bytes = File(...), form_data: str = Form(...)):
        return {"form_data": form_data, "file_data": file_data}

    response = client.post(
        "/test2",
        data={"form_data": "hello"},
        files={"file_data": b"world"}
    )
    print(f"Status: {response.status_code}")
    print(f"Body: {response.json()}")
    assert response.status_code == 200

if __name__ == "__main__":
    try:
        test_form_then_file()
        print("test_form_then_file passed")
    except Exception as e:
        print(f"test_form_then_file failed: {e}")

    try:
        test_file_then_form()
        print("test_file_then_form passed")
    except Exception as e:
        print(f"test_file_then_form failed: {e}")

